const users = table('users', {
  id: uuid().primaryKey().defaultRandom(),
  email: varchar(255).notNull().unique(),
  createdAt: timestamp().notNull().defaultNow(),
})

const posts = table('posts', {
  id: serial().primaryKey(),
  authorId: uuid().notNull().references(() => users.id),
  title: text().notNull(),
})

const user = await db.query.users.findFirst({
  where: (_u, eb) => eb('email', '=', 'ada@acme.dev'),
  with: { posts: { limit: 5 } },
})

CREATE TABLE "bookings" (
  "id" serial PRIMARY KEY,
  "user_id" uuid REFERENCES "users" ("id")
);

await db.transaction({ isolation: 'serializable' }, async (tx) => {
  const user = await tx.insertInto('users').values({ email })
    .returningAll().executeTakeFirstOrThrow()
  await tx.insertInto('profiles').values({ userId: user.id }).execute()
}) // commits on success, rolls back on throw
